import codecs
events = []
def handler(error):
    events.append((type(error).__name__, error.start, error.end))
    if isinstance(error, UnicodeEncodeError):
        return ('?', error.end)
    return ('\ud800', error.end)
codecs.register_error('strict', handler)
try:
    exec(b'# coding: ascii\n#\xff\nvalue = 42')
    print('ok', globals().get('value'))
except BaseException as error:
    print(type(error).__name__, str(error))
print(events)

